package dev.workshopvideo;
import android.app.Activity;import android.content.res.ColorStateList;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.function.Consumer;
/** Live controls, shared by every locally supported wallpaper type. */
final class EffectPanel extends LinearLayout {
 private final Activity activity;private final Consumer<JSONObject> changed;private JSONObject value;private final boolean hasSensor;private final String kind;private int layerCount;private float[] layerDepths;private String[] layerNames;private boolean xray;private LinearLayout palette;private TextView paletteHint;
 EffectPanel(Activity activity,JSONObject initial,boolean sensor,String kind,Consumer<JSONObject> changed){super(activity);this.activity=activity;this.changed=changed;this.hasSensor=sensor;this.kind=kind;value=kind.equals("video")?EffectOptions.video(initial):EffectOptions.normalize(initial);setOrientation(VERTICAL);build();}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView label(String s,int size,int color){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(10),0,dp(7));return t;}
 private void heading(String s){addView(label(s,15,Ui.ACCENT));}
 private void changed(){changed.accept(kind.equals("video")?EffectOptions.video(value):EffectOptions.normalize(value));}
 private void toggle(String key,String title,boolean enabled){Switch s=new Switch(activity);s.setText(title);s.setTextSize(13);s.setTextColor(Ui.TEXT);s.setMinHeight(dp(46));s.setPadding(0,dp(6),0,dp(6));s.setChecked(enabled&&value.optBoolean(key,key.equals("xray")));s.setEnabled(enabled);s.setAlpha(enabled?1:.45f);s.setThumbTintList(ColorStateList.valueOf(Ui.ACCENT));s.setOnCheckedChangeListener((b,on)->{VideoApp.put(value,key,on);updatePalette();changed();});addView(s,new LayoutParams(-1,-2));}
 private void slider(String key,String title,float min,float max,String suffix){float initial=(float)value.optDouble(key,key.equals("xraySize")?.3:min);TextView l=label(title+"  "+(key.equals("fallbackPages")?String.valueOf(Math.round(initial)):format(initial))+suffix,12,Ui.TEXT);addView(l);SeekBar b=new SeekBar(activity);b.setMax(1000);b.setProgress(Math.round((initial-min)/(max-min)*1000));b.setProgressTintList(ColorStateList.valueOf(Ui.ACCENT));b.setThumbTintList(ColorStateList.valueOf(Ui.ACCENT));b.setContentDescription(title);b.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){if(!user)return;float v=min+(max-min)*p/1000;if(key.equals("fallbackPages"))v=Math.round(v);VideoApp.put(value,key,v);l.setText(title+"  "+(key.equals("fallbackPages")?String.valueOf(Math.round(v)):format(v))+suffix);changed();}});addView(b,new LayoutParams(-1,dp(36)));}
 private String format(float f){return String.format(Locale.CHINA,"%.2f",f);}
 void sceneLayers(float[] depths,String[] names,boolean xray){layerDepths=depths;layerNames=names;this.xray=xray;if(xray){heading("触摸 X-ray");toggle("xray","按住并拖动查看另一层图片",true);slider("xraySize","揭示范围",.01f,1,"");}int count=depths.length;layerCount=count;heading("分层参数");for(int i=0;i<Math.min(32,count);i++){heading(names!=null&&i<names.length?names[i]:"图层 "+(i+1));if(!value.has("depth"+i))VideoApp.put(value,"depth"+i,depths[i]);if(!value.has("opacity"+i))VideoApp.put(value,"opacity"+i,1);slider("depth"+i,"视差深度",-2,2,"");slider("opacity"+i,"不透明度",0,1,"");slider("layerX"+i,"水平移动",-1,1,"");slider("layerY"+i,"垂直移动",-1,1,"");}}
 private void updatePalette(){if(palette==null)return;boolean active=value.optBoolean("ripple")||value.optBoolean("particles");palette.setVisibility(active?VISIBLE:GONE);String selected=value.optString("color","#a9efd5");LinearLayout colors=(LinearLayout)palette.getChildAt(2);String[] names={"薄荷绿","天空蓝","樱花粉","暖金色","白色"};String chosen="";for(int i=0;i<colors.getChildCount();i++){TextView view=(TextView)colors.getChildAt(i);boolean on=selected.equalsIgnoreCase(String.valueOf(view.getTag()));view.setSelected(on);view.setText(on?"✓":"●");android.graphics.drawable.GradientDrawable bg=AppSheet.background(on?0xff243e40:Ui.PANEL,dp(14));bg.setStroke(dp(on?2:1),on?Color.parseColor(selected):0xff263343);android.widget.LinearLayout.LayoutParams lp=(LayoutParams)view.getLayoutParams();lp.setMargins(dp(3),0,dp(3),0);view.setBackground(bg);view.setContentDescription(names[i]+(on?"，已选择":""));if(on)chosen=names[i];}paletteHint.setText("已选："+chosen+" · 仅改变波纹与粒子颜色");}
 private void choice(String key,String title,String[] keys,String[] labels){String current=value.optString(key,keys[0]);int index=java.util.Arrays.asList(keys).indexOf(current);TextView row=label(title+"  ·  "+labels[Math.max(0,index)]+"  ›",14,Ui.TEXT);row.setMinHeight(dp(48));row.setBackground(AppSheet.background(Ui.PANEL,dp(12)));row.setPadding(dp(12),dp(10),dp(12),dp(10));row.setOnClickListener(v->{AppSheet sheet=new AppSheet(activity,title,"",null);for(int i=0;i<keys.length;i++){if(key.equals("motionMode")&&keys[i].equals("device")&&!hasSensor)continue;final int item=i;sheet.action("wallpaper",labels[i],keys[i].equals(value.optString(key))?"已选":"",false,()->{VideoApp.put(value,key,keys[item]);if(key.equals("motionMode")){VideoApp.put(value,"pan",keys[item].equals("scroll"));VideoApp.put(value,"gyro",keys[item].equals("device"));VideoApp.put(value,"touch",false);VideoApp.put(value,"ripple",false);VideoApp.put(value,"particles",false);}build();changed();});}sheet.show();});addView(row,new LayoutParams(-1,-2));}
 private void backgroundColor(){String selected=value.optString("backgroundColor","#000000");TextView l=label("背景颜色  ·  "+selected+"  ›",13,Ui.TEXT);l.setOnClickListener(v->{AppSheet sheet=new AppSheet(activity,"背景颜色","用于画面未覆盖的区域",null);String[] colors={"#000000","#ffffff","#182433","#31514b","#452a3c"};for(String color:colors)sheet.action("wallpaper",color,selected.equalsIgnoreCase(color)?"已选":"",false,()->{VideoApp.put(value,"backgroundColor",color);build();changed();});EditText custom=new EditText(activity);custom.setSingleLine(true);custom.setTextColor(Ui.TEXT);custom.setText(selected);custom.setHint("#RRGGBB");sheet.field(custom);sheet.footerButton("使用自定义颜色",true,()->{String c=custom.getText().toString().trim();if(!c.matches("#[0-9a-fA-F]{6}")){custom.setError("请输入 #RRGGBB");return;}VideoApp.put(value,"backgroundColor",c);sheet.dialog.dismiss();build();changed();});sheet.show();});addView(l);}
 private void buildVideo(){removeAllViews();heading("视频画面");toggle("flip","水平镜像",true);choice("motionMode","运动响应",new String[]{"disabled","device","scroll"},new String[]{"关闭",hasSensor?"设备倾斜":"设备倾斜（无传感器）","桌面滚动"});if(value.optString("motionMode").equals("device"))slider("strength","运动强度",0,1,"");slider("speed","播放速度",.25f,2,"×");backgroundColor();toggleRebuild("showColorOptions","显示颜色选项");if(value.optBoolean("showColorOptions",true)){slider("brightness","亮度",.2f,1.8f,"×");slider("contrast","对比度",0,2,"×");slider("saturation","饱和度",0,2,"×");slider("hue","色相偏移",-180,180,"°");}choice("alignment","对齐方式",new String[]{"cover","fill","free"},new String[]{"覆盖 Cover（保持比例裁切）","拉伸 Fill","自由 Free（保持比例完整显示）"});if(value.optString("alignment").equals("free")){slider("zoom","缩放",1,2.5f,"×");slider("x","水平位置",-.5f,.5f,"");slider("y","垂直位置",-.5f,.5f,"");}if(value.optString("motionMode").equals("scroll")){heading("桌面滚动");choice("pageMode","图片分割页数",new String[]{"auto","manual"},new String[]{"自动（按画面尺寸，优先系统页数）","自定义"});if(value.optString("pageMode").equals("manual"))slider("fallbackPages","自定义页数",1,12," 页");addView(label("自动模式按画面比例分割；系统提供可靠页数时同步实际页数。自定义仅控制背景分段，不改变桌面布局。",11,Ui.MUTED));}heading("节能");toggle("batteryStatic","系统省电模式下暂停为静态画面",true);addView(label("保留当前画面，暂停播放和交互；退出省电模式后自动恢复。",11,Ui.MUTED));TextView reset=label("重置视频设置",13,Ui.ACCENT);reset.setOnClickListener(v->{value=EffectOptions.normalize(null);VideoApp.put(value,"zoom",1);VideoApp.put(value,"motionMode","disabled");build();changed();});addView(reset);}
 private void toggleRebuild(String key,String title){Switch control=new Switch(activity);control.setText(title);control.setTextColor(Ui.TEXT);control.setTextSize(13);control.setThumbTintList(ColorStateList.valueOf(Ui.ACCENT));control.setMinHeight(dp(46));control.setChecked(value.optBoolean(key,true));control.setOnCheckedChangeListener((v,on)->{VideoApp.put(value,key,on);build();changed();});addView(control);}
 private void build(){if(kind.equals("video")){buildVideo();return;}palette=null;removeAllViews();heading("运动与交互");toggle("gyro",hasSensor?"随手机倾斜产生视差":"此设备未提供可用姿态传感器",hasSensor);toggle("touch","触摸拖动画面",true);toggle("reverseX","反转水平倾斜",true);toggle("reverseY","反转垂直倾斜",true);slider("strength","倾斜强度",0,1,"");slider("smooth","运动平滑时间",.03f,1," 秒");slider("touchStrength","拖动幅度",0,1,"");choice("pageMode","图片分割页数",new String[]{"auto","manual"},new String[]{"自动（画面尺寸／系统页数）","自定义"});if(value.optString("pageMode").equals("manual"))slider("fallbackPages","自定义桌面页数",1,12," 页");addView(label("自动按画面比例分割，优先使用系统提供的页数；也可自定义分段。",11,Ui.MUTED));
  heading("节能");toggle("batteryStatic","系统省电模式下暂停为静态画面",true);heading("构图与画面");slider("zoom","缩放",1,2.5f,"×");slider("x","水平位置",-.5f,.5f,"");slider("y","垂直位置",-.5f,.5f,"");slider("rotation","画面旋转",-15,15,"°");slider("brightness","亮度",.2f,1.8f,"×");slider("saturation","饱和度",0,2,"×");if(kind.equals("scene"))slider("layerDepth","分层视差深度",0,2,"×");
  heading("动画与叠加");toggle("ripple","触摸波纹",true);toggle("particles","漂浮粒子",true);slider("particleCount","粒子数量",4,100,"");if(!kind.equals("animated"))slider("speed",kind.equals("video")?"视频播放速度":"粒子运动速度",.25f,2,"×");slider("fps","绘制帧率",15,60," FPS");
  palette=new LinearLayout(activity);palette.setOrientation(VERTICAL);palette.addView(label("波纹与粒子颜色",13,Ui.TEXT));paletteHint=label("",12,Ui.MUTED);palette.addView(paletteHint);LinearLayout colors=new LinearLayout(activity);String[] values={"#a9efd5","#8ebdff","#ffadc4","#ffd48e","#ffffff"},names={"薄荷绿","天空蓝","樱花粉","暖金色","白色"};
  for(int i=0;i<values.length;i++){final String color=values[i],name=names[i];TextView choice=label("",24,Color.parseColor(color));choice.setTag(color);choice.setGravity(Gravity.CENTER);choice.setPadding(0,0,0,0);choice.setContentDescription(name);choice.setOnClickListener(v->{VideoApp.put(value,"color",color);updatePalette();choice.announceForAccessibility("已选择"+name);changed();});colors.addView(choice,new LayoutParams(0,dp(46),1));}palette.addView(colors);addView(palette);updatePalette();

  TextView reset=label("恢复默认效果",13,Ui.ACCENT);reset.setGravity(Gravity.CENTER);reset.setMinHeight(dp(46));reset.setOnClickListener(v->{value=EffectOptions.normalize(null);build();changed();});addView(reset);if(layerCount>0)sceneLayers(layerDepths,layerNames,xray);
 }
}
